// Nodes after the MCP Server Trigger are exposed as tools;
// this one's name and the workflow's tool description are
// what a calling agent sees.
const day = ($input.first().json.weekday || '').toLowerCase();
const hours = { monday: '8am to 6pm', tuesday: '8am to 6pm', wednesday: '8am to 6pm', thursday: '8am to 6pm', friday: '8am to 6pm', saturday: 'closed', sunday: 'closed' };
return [{ json: { weekday: day, hours: hours[day] || 'unknown day' } }];
